<?php require 'config/database.php';require 'config/app.php';$pageTitle='Tournament lineup';$active='tournaments';$filter=$_GET['status']??'all';$sql="SELECT * FROM tournaments";$args=[];if(in_array($filter,['open','upcoming','live','completed'],true)){$sql.=" WHERE status=?";$args[]=$filter;}$sql.=" ORDER BY tournament_date";$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();require 'includes/header.php';?>
<section class="page-hero"><div class="eyebrow">THE COMPETITIVE CALENDAR</div><h1>FIND YOUR <span>LOBBY.</span></h1><p>Choose your tournament, check the rules, and get your squad ready.</p></section><div class="filters"><?php foreach(['all'=>'All lobbies','open'=>'Registration open','upcoming'=>'Upcoming','live'=>'Live','completed'=>'Completed'] as $k=>$v):?><a class="<?=$filter===$k?'selected':''?>" href="?status=<?=$k?>"><?=e($v)?></a><?php endforeach;?></div><div class="row g-4 section"><?php foreach($rows as $i=>$t):?><div class="col-md-6 col-xl-4"><article class="tour-card"><div class="tour-art art<?=($i%3)+1?>"><span class="tag"><?=e(strtoupper($t['status']))?></span><small>BA / <?=str_pad((string)$t['tournament_id'],3,'0',STR_PAD_LEFT)?></small><strong><?=e($t['short_label'])?></strong></div><div class="tour-body"><div class="meta"><span><?=e(date('d M Y',strtotime($t['tournament_date'])))?></span><span><?=e($t['mode'])?></span></div><h3><?=e($t['name'])?></h3><p><?=e($t['description'])?></p><div class="tour-stats"><div><small>ENTRY</small><b><?=$t['entry_fee']>0?'₹'.number_format($t['entry_fee']):'FREE'?></b></div><div><small>PRIZE POOL</small><b class="hot-text">₹<?=number_format($t['prize_pool'])?></b></div><div><small>MAX TEAMS</small><b><?=(int)$t['max_teams']?></b></div></div><a class="btn btn-card w-100" href="tournament.php?id=<?=(int)$t['tournament_id']?>">Tournament details ↗</a></div></article></div><?php endforeach;if(!$rows):?><div class="empty"><h3>No tournaments found.</h3></div><?php endif;?></div><?php require 'includes/footer.php';?>
